const enterBeforeLiveDesign=$('#detailEdit').onclick;$('#detailEdit').onclick=()=>{const css=captureDetailLayout();enterBeforeLiveDesign();focusDialog.classList.add('live-design');focusDialog.classList.remove('editing-profile','mobile-info-open');liveDesignStyle.textContent=css;canvasTools.classList.add('inspector-folded');collapseInspector.textContent='＋';collapseInspector.setAttribute('aria-label','편집창 펼치기');selectCanvasLayer('poster');toast('캐릭터를 드래그해 배치하세요 · 도구는 ＋로 펼치기')};
