// Preserve the real rendered scene, including backgrounds and pseudo elements.
captureDetailLayout=function(){focusDialog.getAnimations({subtree:true}).forEach(a=>{try{a.finish()}catch{a.cancel()}});const stage=$('#posterStage'),nodes=[focusDialog,stage,...stage.querySelectorAll('*')];return nodes.map((el,i)=>{el.dataset.liveLayout=i;const selector='#characterFocus#characterFocus#characterFocus.live-design'+(el===focusDialog?'':` [data-live-layout="${i}"]`);return ['',':before',':after'].map(pseudo=>{const cs=getComputedStyle(el,pseudo||null);const omitted=new Set(['animation','animation-name','transition','transition-property','pointer-events','cursor','touch-action']);if(el.matches('[data-art],.user-canvas-object'))['transform','translate','rotate','scale','background-image'].forEach(p=>omitted.add(p));const declarations=[...cs].filter(p=>!p.startsWith('--')&&!omitted.has(p)&&!p.startsWith('animation-')&&!p.startsWith('transition-')).map(p=>p+':'+cs.getPropertyValue(p)+'!important');return selector+pseudo+'{'+declarations.join(';')+'}'}).join('\n')}).join('\n')};
$('#detailEdit').onclick=()=>{const css=captureDetailLayout();liveDesignStyle.textContent=css;focusDialog.classList.add('canvas-editing','live-design');focusDialog.classList.remove('editing-profile','mobile-info-open');$('#canvasName').value=chars[selected].name;canvasTools.classList.add('inspector-folded');collapseInspector.textContent='＋';collapseInspector.setAttribute('aria-label','편집창 펼치기');selectCanvasLayer('poster');undoEdits=[];redoEdits=[];historyCurrent=null;commitEditorHistory();toast('상세페이지 위에서 바로 배치 · ＋ 도구 펼치기')};
