// Keep removed slots available when the user increases the cast again.
let parkedCharacters=[];
const castControl=document.createElement('div');castControl.className='cast-count-control';
castControl.innerHTML='<button type="button" class="cast-count-toggle" aria-label="캐릭터 인원 관리" title="캐릭터 인원 관리" aria-expanded="false" aria-controls="castCountPopover"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 4v2"/></svg></button><div id="castCountPopover" class="cast-count-popover" hidden><button type="button" data-count="-1" aria-label="캐릭터 수 줄이기" title="뺄 캐릭터 선택">−</button><output aria-live="polite"></output><button type="button" data-count="1" aria-label="캐릭터 추가" title="캐릭터 추가 · 최대 5명">＋</button></div>';
$('#canvas').append(castControl);
function updateCastControl(){castControl.querySelector('output').textContent=chars.length+'명';castControl.querySelector('[data-count="-1"]').disabled=chars.length<=1;castControl.querySelector('[data-count="1"]').disabled=chars.length>=5;$('#canvas').dataset.castCount=chars.length;$('.poster-bottom span:last-child').textContent=String(selected+1).padStart(2,'0')+' / '+String(chars.length).padStart(2,'0');}
function freshCastProfile(){return completeProfile({description:'아직 기록되지 않은 이야기.\n이 캐릭터만의 세계와 이야기를 소개해 주세요.',traits:['나만의 특성','특별한 재능','소중한 가치'],personality:'이 캐릭터의 성격을 소개해 주세요.',memories:['','','']});}
function changeCastCount(delta){if(delta<0)showCastRemoval();else showCastAddition();}
castControl.querySelectorAll('[data-count]').forEach(b=>b.onclick=()=>changeCastCount(Number(b.dataset.count)));
const castToggle=castControl.querySelector('.cast-count-toggle'),castPopover=castControl.querySelector('.cast-count-popover');
function setCastPopover(open){castRemoval.hidden=true;castPopover.hidden=!open;castToggle.setAttribute('aria-expanded',String(open));}
castToggle.onclick=()=>setCastPopover(castToggle.getAttribute('aria-expanded')!=='true');
document.addEventListener('pointerdown',e=>{if(!castControl.contains(e.target))setCastPopover(false)});
castControl.addEventListener('keydown',e=>{if(e.key==='Escape'){setCastPopover(false);castToggle.focus();e.stopPropagation()}});
const renderBeforeCastCount=render;render=function(){renderBeforeCastCount();updateCastControl()};
const restoreBeforeCastCount=restoreProject;restoreProject=function(state){if(state?.chars?.length){const count=Math.max(1,Math.min(5,state.chars.length));while(chars.length<count)chars.push(createCharacter('Character '+(chars.length+1),0));chars.length=count;state.selected=Math.min(Math.max(0,state.selected||0),count-1);parkedCharacters=(state.parkedCharacters||[]).map(item=>{const c=createCharacter(item.character.name,0);c.theme=item.character.theme;sceneKeys.forEach(k=>Object.assign(c.scenes[k],item.character.scenes[k]));return {character:c,profile:item.profile||freshCastProfile(),index:item.index}});}restoreBeforeCastCount(state);updateCastControl()};
const snapshotBeforeCastCount=projectSnapshot;projectSnapshot=async()=>{const state=await snapshotBeforeCastCount();state.parkedCharacters=await Promise.all(parkedCharacters.map(async({character:c,profile,index})=>({profile,index,character:{name:c.name,theme:c.theme,scenes:Object.fromEntries(await Promise.all(sceneKeys.map(async key=>{const {name,...scene}=c.scenes[key];return[key,{...scene,url:scene.url?await asData(scene.url):null,originalUrl:scene.originalUrl?await asData(scene.originalUrl):null}]})))}})));return state};
updateCastControl();

const castRemoval=document.createElement('div');castRemoval.className='cast-removal';castRemoval.hidden=true;castControl.append(castRemoval);
function castSheet(title,hint){castPopover.hidden=true;castRemoval.replaceChildren();const head=document.createElement('div');head.className='cast-sheet-head';const back=document.createElement('button');back.type='button';back.textContent='‹';back.setAttribute('aria-label','인원 메뉴로 돌아가기');back.onclick=()=>setCastPopover(true);const heading=document.createElement('strong');heading.textContent=title;head.append(back,heading);const note=document.createElement('small');note.textContent=hint;castRemoval.append(head,note);castRemoval.hidden=false;return castRemoval;}
function castChoice(c,index,action,symbol='−'){const button=document.createElement('button');button.type='button';button.className='cast-removal-item';button.setAttribute('aria-label',c.name+(symbol==='−'?' 보관하고 빼기':' 복구'));const image=document.createElement('span');image.className='cast-removal-picture';if(c.scenes.slot.url)image.style.backgroundImage='url("'+c.scenes.slot.url+'")';else image.textContent=String(index+1).padStart(2,'0');const label=document.createElement('span');label.textContent=c.name;const icon=document.createElement('span');icon.textContent=symbol;icon.setAttribute('aria-hidden','true');button.append(image,label,icon);button.onclick=action;castRemoval.append(button);}
function showCastRemoval(){if(chars.length<=1)return;castSheet('뺄 캐릭터 선택','이미지와 설정은 보관됩니다.');chars.forEach((c,i)=>castChoice(c,i,()=>removeCastMember(i)));castRemoval.querySelector('button')?.focus();}
function showCastAddition(){if(chars.length>=5)return;castSheet('캐릭터 추가',chars.length+' / 5명 · 추가할 방법을 선택하세요');const fresh=document.createElement('button');fresh.type='button';fresh.className='cast-new-choice';fresh.innerHTML='<span aria-hidden="true">＋</span><span>새 캐릭터 추가<small>빈 슬롯에서 새로 시작</small></span>';fresh.onclick=()=>addCastMember();castRemoval.append(fresh);const label=document.createElement('p');label.className='cast-archive-label';label.textContent='보관한 캐릭터 복구 · '+parkedCharacters.length;castRemoval.append(label);if(!parkedCharacters.length){const empty=document.createElement('p');empty.className='cast-empty-note';empty.textContent='보관한 캐릭터가 없어요.';castRemoval.append(empty)}else parkedCharacters.forEach((saved,i)=>castChoice(saved.character,i,()=>addCastMember(i),'↶'));fresh.focus();}
function addCastMember(archiveIndex){if(chars.length>=5)return;const saved=Number.isInteger(archiveIndex)?parkedCharacters.splice(archiveIndex,1)[0]:null;let n=chars.length+1;while([...chars,...parkedCharacters.map(v=>v.character)].some(c=>c.name==='Character '+String(n).padStart(2,'0')))n++;const c=saved?.character||createCharacter('Character '+String(n).padStart(2,'0'),0);if(!saved)Object.values(c.scenes).forEach(scene=>scene.empty=true);const index=Math.min(saved?.index??chars.length,chars.length);chars.splice(index,0,c);characterProfiles.splice(index,0,saved?.profile||freshCastProfile());selected=index;setCastPopover(false);render();scheduleProjectSave();if(saved){castToggle.focus();toast(c.name+' 캐릭터를 복구했어요.')}else{previewMode='slot';syncSceneButtons();toggleEditor(true);toast('이미지 하나로 선택 화면과 상세페이지를 함께 시작해요.');}}
function removeCastMember(index){if(chars.length<=1||!chars[index])return;const c=chars[index];parkedCharacters.unshift({character:c,profile:characterProfiles[index],index});chars.splice(index,1);characterProfiles.splice(index,1);if(selected>index)selected--;else if(selected===index)selected=Math.min(index,chars.length-1);setCastPopover(false);render();scheduleProjectSave();castToggle.focus();toast(c.name+' 캐릭터를 보관했어요. ＋로 복구할 수 있어요.');}

// First upload seeds only untouched primary views, leaving existing artwork alone.
const uploadBeforeFirstCharacter=upload;
upload=async function(file){const owner=chars[selected],target=activeImage(),previous=target.uploadRevision;await uploadBeforeFirstCharacter(file);if(!file||!target.url||target.uploadRevision===previous)return;const {name,...image}=target;for(const key of ['slot','diamond','poster']){const scene=owner.scenes[key];if(scene!==target&&scene.empty&&!scene.url)Object.assign(scene,image);}if(chars[selected]===owner){render();preparePoster(null,selected);}scheduleProjectSave();};
// Use the same action name for an empty image and its visible button.
const updateTouchBeforeUploadHint=updateTouchCanvas;
updateTouchCanvas=function(){updateTouchBeforeUploadHint();if(activeImage().empty){$('#touchReplace').textContent='＋ 캐릭터 이미지 추가';$('#sceneStatus').textContent='첫 이미지는 선택 화면과 상세페이지에 함께 적용됩니다.';}};

